 {
 	const struct mtk_dsi_driver_data *data = dsi->driver_data;
@@ -961,6 +1154,10 @@ static int mtk_dsi_poweron(struct mtk_dsi *dsi)
 	mtk_dsi_reset_engine(dsi);
